before.content:
assertEquals(0, created.revision());
assertEquals(List.of("session-1"), repository.list().stream()
        .map(SessionDocument.Metadata::sessionId).toList());
assertEquals(created, repository.load("session-1").orElseThrow());
assertThrows(IllegalStateException.class,
        () -> repository.create("session-1", MODEL, "workspace", NOW));

after.content:
assertEquals(0, created.revision());
assertEquals(List.of("session-1"), repository.list().stream()
        .map(SessionDocument.Metadata::sessionId).toList());
SessionRepository.SessionSummary summary = repository.listSummaries().getFirst();
assertEquals("session-1", summary.sessionId());
assertEquals("workspace", summary.workingDirectory());
assertEquals(0, summary.revision());
assertEquals(NOW, summary.updatedAt());
assertEquals(created, repository.load("session-1").orElseThrow());
assertThrows(IllegalStateException.class,
        () -> repository.create("session-1", MODEL, "workspace", NOW));
